// import { useState } from "react";
import { connect } from 'react-redux'
import { Button, Form, Table, Input, message, Typography } from 'antd'

import { AddformWrapper } from './index.style'
import { useEffect, useState } from 'react'
const FormItem = Form.Item
const { Text } = Typography

const columns = [
  {
    title: 'Label',
    dataIndex: 'label',
    key: 'label'
  },
  {
    title: 'Mandatory',
    dataIndex: 'mandatory',
    key: 'mandatory'
  },
  {
    title: 'Doc Verification Required',
    dataIndex: 'doc_verification_required',
    key: 'doc_verification_required'
  },
  {
    title: 'Multiple Value Required',
    dataIndex: 'multiple_value_required',
    key: 'multiple_value_required'
  },
  {
    title: 'Type',
    dataIndex: 'type',
    key: 'type'
  },
  {
    title: 'Internal',
    dataIndex: 'internal',
    key: 'internal'
  },
  {
    title: 'Regex Validation',
    dataIndex: 'regex_validation',
    key: 'regex_validation'
  },
  {
    title: 'User Guideline',
    dataIndex: 'user_guideline',
    key: 'user_guideline'
  },
  {
    title: 'Action',
    dataIndex: 'action',
    key: 'action',
    align: 'center'
  }
]

const defaultFormDetail = {
  formType: 'claim',
  is_active: true,
  title: '',
  description: '',
  attributes: []
}

function AddForm (props) {
  const {
    form,
    searchAttributeResult,
    payload,
    setPayload,
    saveFormNow,
    setSaveFormNow,
    setWhichForm,
    formId,
    setFormId,
    isEdit,
    setIsLoading
  } = props
  const { getFieldDecorator } = form
  const [documentsData, setDocumentsData] = useState([])
  const [searchDocuments, setSearchDocuments] = useState([])
  const [dataSource, setDataSource] = useState([])
  const [listDocumentId, setListDocumentId] = useState([])
  const [formDetail, setFormDetail] = useState({ ...defaultFormDetail })

  useEffect(() => {
    if (searchAttributeResult) {
      setDocumentsData(searchAttributeResult)
    }
  }, [searchAttributeResult])

  useEffect(() => {
    if (searchDocuments?.length > 0) {
      const newDataSource = []
      for (let i = 0; i < searchDocuments?.length; i++) {
        const doc = searchDocuments[i]
        const newData = {
          label: doc.label,
          mandatory: doc?.required ? 'Yes' : 'No',
          doc_verification_required: doc?.validation_required ? 'Yes' : 'No',
          multiple_value_required: doc?.is_multiple_value_required
            ? 'Yes'
            : 'No',
          type: doc?.type,
          internal: doc?.is_internal ? 'Yes' : 'No',
          regex_validation: '-',
          user_guideline: '-',
          action: listDocumentId.some(
            (item) => item.master_attribute_id === doc?.master_attribute_id
          )
            ? (
              <Button className='delete' onClick={() => handleAddRemove(doc)}>
                REMOVE
              </Button>
              )
            : (
              <Button className='add' onClick={() => handleAddRemove(doc)}>
                ADD
              </Button>
              )
        }
        newDataSource.push(newData)
      }
      setDataSource(newDataSource)
    }
  }, [searchDocuments])

  useEffect(() => {
    if (saveFormNow) {
      setSaveFormNow(false)
      if (listDocumentId?.length > 0 && formDetail.title && formDetail.description) {
        const combineFormDetail = { ...formDetail }
        const newPayload = { ...payload }
        combineFormDetail.attributes = listDocumentId
        if (formId || formId === 0) {
          newPayload.forms_data.splice(formId, 1, combineFormDetail)
        } else newPayload.forms_data.push(combineFormDetail)
        setWhichForm('list')
        setPayload(newPayload)
        if (formId || formId === 0) setFormId(null)
      } else {
        message.error('Please fill all the fields')
      }
    }
    setIsLoading(false)
  }, [saveFormNow])

  useEffect(() => {
    if ((formId || formId === 0) && documentsData?.length > 0) {
      const newFormDetail = { ...payload?.forms_data[formId] }
      setSearchDocuments(newFormDetail.attributes)
      setListDocumentId(newFormDetail.attributes)
      //   findAddedDocument({ ...payload?.forms_data[formId]?.attributes });
      setFormDetail(newFormDetail)
    }
  }, [formId, documentsData])

  //   const findAddedDocument = (docs) => {
  //     const res = [];
  //     for (let i = 0; i < docs?.length; i++) {
  //       const doc = docs[i];
  //       const index = documentsData.findIndex(
  //         (item) => item.master_attribute_id === doc?.master_attribute_id
  //       );
  //       res.push({
  //         master_attribute_id: doc?.master_attribute_id,
  //         name: doc?.name,
  //         label: doc?.label,
  //         required: doc.required,
  //         is_internal: doc?.is_internal,
  //         validation_required: doc?.validation_required,
  //         is_multiple_value_required: doc?.is_multiple_value_required,
  //         type: doc?.type,
  //       });
  //     }
  //   };

  const handleAddRemove = (doc) => {
    const newListDocumentId = [...listDocumentId]
    const index = newListDocumentId.findIndex(
      (item) => item.master_attribute_id === doc?.master_attribute_id
    )

    if (index !== -1) {
      newListDocumentId.splice(index, 1)
    } else {
      newListDocumentId.push(doc)
    }

    setListDocumentId(newListDocumentId)
    setSearchDocuments([...searchDocuments])
  }

  function searchByKeyword (array, keyword) {
    const results = array
      .filter((item) =>
        item.label.toLowerCase().includes(keyword.toLowerCase())
      )
      .map((item) => {
        return {
          master_attribute_id: item?.id,
          name: item?.name,
          label: item?.label,
          required: true,
          is_internal: !!item?.is_internal,
          validation_required: true,
          is_multiple_value_required: !!item?.is_multiple_value_required,
          type: item?.type
        }
      })
    return results
  }

  const handleSearch = (e) => {
    if (documentsData?.length > 0) {
      const res = searchByKeyword(documentsData, e.target.value)
      setSearchDocuments(res)
    }
  }

  const handleChange = (e, attribute) => {
    const newFormDetail = { ...formDetail }
    newFormDetail[attribute] = e.target.value
    setFormDetail(newFormDetail)
  }

  return (
    <AddformWrapper>
      <Form className='questionnaire__form-wrapper'>
        <div className='questionnaire__addform-oneline'>
          <FormItem label='Form Name'>
            {isEdit && formDetail?.title
              ? (
                <div style={{ marginLeft: '10px' }}><Text strong>{formDetail?.title}</Text></div>
                )
              : (
                <Input
                  onChange={(e) => handleChange(e, 'title')}
                  value={formDetail?.title}
                  placeholder='Add Form Name'
                />
                )}
          </FormItem>
          <FormItem label='Description'>
            {getFieldDecorator('description', {
              rules: [{ required: true, message: 'Please input description!' }],
              initialValue: formDetail?.description
            })(
              <Input
                onChange={(e) => handleChange(e, 'description')}
                value={formDetail?.description}
                placeholder='Add Description'
              />
            )}
          </FormItem>
        </div>
        <div className='questionnaire__table-wrapper'>
          <label>Select Documents To Add</label>
          <Table
            style={{ overflow: 'auto' }}
            dataSource={dataSource}
            columns={columns}
          />
        </div>
        <div className='questionnaire__search-wrapper'>
          <div className='questionnaire__search-wrapper__input'>
            <label>Search Document</label>
            <Input
              placeholder='Find Document'
              onChange={handleSearch}
              onPressEnter={() => {}}
              style={{ display: 'block' }}
            />
          </div>
        </div>
      </Form>
    </AddformWrapper>
  )
}

const CommonForm = Form.create()(AddForm)
const mapSateToProps = (state) => ({
  searchAttributeLoading: state.Loading.SEARCH_ATTRIBUTE,
  searchAttributeError: state.Error.SEARCH_ATTRIBUTE,
  searchAttributeResult: state.Claims.searchAttributeResult.attributes
})

export default connect(mapSateToProps, {})(CommonForm)
