import { useEffect, useLayoutEffect, useRef, useState } from 'react'
import { connect } from 'react-redux'
import { Button, Modal, Spin, Table } from 'antd'

import DeleteIcon from '../../../../image/delete.png'
import EditIcon from '../../../../image/edit.png'

import { QuestionnaireWrapper } from './index.style'
import DeleteForm from './DeleteForm'
import AddForm from './AddForm'
import ClaimActions from '../../../redux/claims/actions'
import ListForm from './ListForm'
import { showNotification } from '../../../../components/ShowNotification'

const {
  getQuestionList,
  deleteQuestionList,
  resetReduxStateClaim,
  searchAttribute,
  addQuestionList
} = ClaimActions

const defaultPayload = {
  display_text: '',
  is_active: true,
  remark: 'text',
  forms_data: []
}

function Questionnaire (props) {
  const {
    getQuestionList,
    deleteQuestionList,
    questionListData,
    searchAttribute,
    addQuestionList,
    deleteQuestionStatus,
    addQuestionStatusLoading,
    deleteQuestionStatusLoading,
    addQuestionStatus,
    resetReduxStateClaim,
    getQuestionListDataLoading,
    addQuestionMessage,
    addQuestionStatusData,
    deleteQuestionStatusData
  } = props
  const firstUpdate = useRef(true)

  const [show, setShow] = useState(false)
  const [saveFormNow, setSaveFormNow] = useState(false)
  const [whichForm, setWhichForm] = useState('list')
  const [formId, setFormId] = useState(null)
  const [questions, setQuestions] = useState([])
  const [page, setPage] = useState(1)
  const [size, setSize] = useState(10)
  const [pagination, setPagination] = useState(null)
  const [selected, setSelectedItem] = useState(null)
  const [firstTime, setFirstTime] = useState(true)
  const [payload, setPayload] = useState({ ...defaultPayload })
  const [uniqueId, setUniqueId] = useState(Date.now())
  const [isEdit, setIsEdit] = useState(false)
  const [loading, setIsLoading] = useState(false)

  useLayoutEffect(() => {
    if (firstUpdate.current) {
      firstUpdate.current = false
    }
  })

  useEffect(() => {
    searchAttribute()
  }, [])

  useEffect(() => {
    if (!show) resetDefaultState()
  }, [show])

  useEffect(() => {
    const query = {
      page: page,
      page_size: size,
      add_forms: true,
      sort_by: 'created_at'
    }
    getQuestionList(query)
  }, [size, page, uniqueId])

  useEffect(() => {
    if (addQuestionStatus?.success || deleteQuestionStatus?.success) {
      resetDefaultState()
      setUniqueId(Date.now())
    }
  }, [addQuestionStatus, deleteQuestionStatus])

  useEffect(() => {
    const erorr = addQuestionMessage || 'error'
    if (addQuestionStatusData === 'error') {
      showNotification('error', erorr)
      setIsLoading(false)
    }
    resetReduxStateClaim(['addQuestionMessage', 'addQuestionStatusData', 'deleteQuestionStatusData'])
    setIsLoading(false)
    setIsEdit(false)
  }, [addQuestionMessage, addQuestionStatusData, deleteQuestionStatusData])

  useEffect(() => {
    if (questionListData?.data?.length > 0) {
      const newQuestions = []
      const data = questionListData?.data
      for (let i = 0; i < data?.length; i++) {
        newQuestions.push({
          key: i + 1,
          no: `${i + 1 - size + page * size}. `,
          questions: data[i].display_text,
          isActive: data[i].is_active,
          action: (
            <div className='questionnaire__action-wrapper'>
              <span
                style={{ background: '#D2E6FA' }}
                onClick={() => {
                  setIsEdit(true)
                  handleShowItem('list', data[i], isEdit)
                }}
              >
                <img src={EditIcon} height='16px' width='16px' />
              </span>
              {data[i].is_active && (
                <span
                  style={{ background: '#FADCDC' }}
                  onClick={() => handleShowItem('delete', data[i])}
                >
                  <img src={DeleteIcon} height='16px' width='16px' />
                </span>
              )}
            </div>
          )
        })
        setQuestions(newQuestions)
      }
    }
    if (questionListData?.meta_data) {
      setPagination(questionListData.meta_data)
    }
  }, [questionListData])

  useEffect(() => {
    if (formId || formId === 0) {
      setWhichForm('edit')
    }
  }, [formId])

  const columns = [
    {
      title: 'No.',
      dataIndex: 'no',
      key: 'no',
      align: 'center',
      width: '80px'
    },
    {
      title: 'Questions',
      dataIndex: 'questions',
      key: 'questions'
    },
    {
      title: 'Action',
      dataIndex: 'action',
      key: 'action',
      align: 'center',
      width: '150px'
    },
    {
      title: 'Remarks',
      dataIndex: 'isActive',
      key: 'isActive',
      align: 'center',
      width: '150px',
      render: (val) => {
        return <div style={val ? { color: '#009632', textAlign: 'center' } : { color: '#999999', textAlign: 'center' }}>{val === true ? 'Active' : 'Inactive'}</div>
      }
    }
  ]
  const resetDefaultState = () => {
    setFirstTime(true)
    setShow(false)
    setSaveFormNow(false)
    setWhichForm('list')
    setFormId(null)
    setSelectedItem(null)
    setPayload({ ...defaultPayload })
  }

  const handleShow = (type) => {
    setWhichForm(type)
    setShow(true)
  }

  const handleShowItem = (type, item) => {
    setSelectedItem(item)
    handleShow(type)
  }
  const handleClose = () => {
    if (whichForm === 'add' || whichForm === 'edit') {
      setSaveFormNow(false)
      setFormId(false)
      setWhichForm('list')
    } else if (whichForm === 'add_quest') {
      setShow(false)
      setWhichForm('add_quest')
      setIsEdit(false)
    } else {
      setShow(false)
      setWhichForm(null)
      setIsEdit(false)
    }
  }

  const handleShowForm = (type) => {
    switch (type) {
      case 'edit':
        return (
          <AddForm
            payload={payload}
            setPayload={setPayload}
            setWhichForm={setWhichForm}
            setSaveFormNow={setSaveFormNow}
            saveFormNow={saveFormNow}
            formId={formId}
            setFormId={setFormId}
            isEdit
            setIsLoading={setIsLoading}
          />
        )
      case 'delete':
        return <DeleteForm selected={selected} />
      case 'add':
        return (
          <AddForm
            payload={payload}
            setPayload={setPayload}
            setWhichForm={setWhichForm}
            setSaveFormNow={setSaveFormNow}
            saveFormNow={saveFormNow}
            setIsLoading={setIsLoading}
          />
        )
      case 'add_quest':
        return (
          <ListForm
            payload={payload}
            setPayload={setPayload}
            setWhichForm={setWhichForm}
            setFormId={setFormId}
            selected={selected}
            firstTime={firstTime}
            setFirstTime={setFirstTime}
            whichForm='add_quest'
          />
        )
      default:
        return (
          <ListForm
            payload={payload}
            setPayload={setPayload}
            setWhichForm={setWhichForm}
            setFormId={setFormId}
            selected={selected}
            firstTime={firstTime}
            setFirstTime={setFirstTime}
          />
        )
    }
  }

  const handleButtonWording = (type) => {
    switch (type) {
      case 'edit':
        return 'EDIT FORM'
      case 'delete':
        return 'DELETE'
      case 'add':
        return 'SAVE FORM'
      default:
        return isEdit ? 'UPDATE QUESTION' : 'SAVE QUESTION'
    }
  }

  const handleHeaderWording = (type) => {
    switch (type) {
      case 'edit':
        return 'Edit Form'
      case 'delete':
        return 'Delete Question'
      case 'add':
        return 'Add Form'
      default:
        return isEdit ? 'Edit Question' : 'Add Question'
    }
  }

  const handleOnOk = (type) => {
    switch (type) {
      case 'edit':
        setSaveFormNow(true)
        break
      case 'delete':
        deleteQuestionList(selected?.id)
        break
      case 'add':
        setSaveFormNow(true)
        break
      default:
        addQuestionList(payload)
        break
    }
  }

  const handlePaginationChange = (e) => {
    setPage(e.current)
    setSize(e.pageSize)
  }

  return (
    <QuestionnaireWrapper>
      <div className='questionnaire__title-wrapper'>
        <h1>Questionnaire: <span style={{ color: '#4482FF' }}>{questionListData?.meta_data?.total_records}</span></h1>
        <Button onClick={() => handleShow('add_quest')}>ADD QUESTION</Button>
      </div>
      <div className='questionnaire__table-wrapper'>
        <Table
          style={{ overflow: 'auto' }}
          dataSource={questions}
          columns={columns}
          loading={getQuestionListDataLoading}
          pagination={{
            pageSize: size,
            total: pagination?.total_records,
            current: page
          }}
          onChange={handlePaginationChange}
        />
      </div>
      <Modal
        title={handleHeaderWording(whichForm)}
        className='modal-questionnaire'
        visible={show}
        onCancel={handleClose}
        width={1200}
        footer={[
          <Button onClick={handleClose} key='1'>
            Cancel
          </Button>,
          <Button
            onClick={() => {
              handleOnOk(whichForm)
              setIsLoading(true)
            }}
            loading={loading}
            key='2'
            type={whichForm === 'delete' ? 'danger' : 'primary'}
            disabled={addQuestionStatusLoading || deleteQuestionStatusLoading || (payload?.forms_data?.filter(data => data.is_active === true).length === 0 && !['edit', 'delete', 'add'].includes(whichForm))}
            style={whichForm === 'delete' ? { background: '#dc0000', color: '#ffffff', border: '3px solid #dc0000' } : {}}
          >
            {handleButtonWording(whichForm)}
          </Button>
        ]}
      >
        <Spin spinning={false}>
          {whichForm ? handleShowForm(whichForm) : null}
        </Spin>
      </Modal>
    </QuestionnaireWrapper>
  )
}

const mapSateToProps = (state) => ({
  questionListData: state.Claims.getQuestionListData,
  getQuestionListDataLoading: state.Loading.GET_QUESTION_LIST,

  addQuestionStatus: state.Claims.addQuestionStatus,
  addQuestionMessage: state.Claims.addQuestionMessage,
  addQuestionStatusData: state.Claims.addQuestionStatusData,
  addQuestionStatusLoading: state.Loading.ADD_QUESTION_LIST,

  deleteQuestionStatus: state.Claims.deleteQuestionStatus,
  deleteQuestionStatusLoading: state.Loading.DELETE_QUESTION_LIST,
  deleteQuestionStatusData: state.Claims.deleteQuestionStatusData
})

export default connect(mapSateToProps, {
  deleteQuestionList,
  addQuestionList,
  getQuestionList,
  resetReduxStateClaim,
  searchAttribute
})(Questionnaire)
