import { connect } from 'react-redux'
import { Button, Form, Table, Input, Typography } from 'antd'
import { ListformWrapper } from './index.style'
import { useEffect, useState } from 'react'

import DeleteIcon from '../../../../image/delete.png'
import EditIcon from '../../../../image/edit.png'

const FormItem = Form.Item
const columns = [
  {
    title: 'No.',
    dataIndex: 'no',
    key: 'no',
    width: '10%'
  },
  {
    title: 'Title',
    dataIndex: 'title',
    key: 'title'
  },
  {
    title: 'Action',
    dataIndex: 'action',
    key: 'action',
    width: '20%'
  }
]

const { Text } = Typography
function ListForm (props) {
  const {
    setWhichForm,
    payload,
    setPayload,
    setFormId,
    selected,
    firstTime,
    setFirstTime,
    whichForm = '',
    payload: { display_text: displayText = '' } = {}
  } = props

  const [dataSource, setDataSource] = useState([])

  useEffect(() => {
    if (selected?.id && firstTime) {
      setFirstTime(false)
      const newPayload = {
        display_text: selected?.display_text,
        is_active: true,
        remark: selected?.remark,
        is_update: true,
        forms_data: selected?.forms_data
      }
      const formData = selected?.forms_data
      const newFormData = [...formData]
      const trueFormData = []
      for (let i = 0; i < newFormData?.length; i++) {
        const newAttributesData = {
          formType: 'claim',
          title: newFormData[i]?.title,
          description: newFormData[i]?.description,
          slug: newFormData[i].slug,
          attributes: [],
          is_active: true
        }
        const newAttributes = formData[i]?.attributes
        for (let k = 0; k < newAttributes?.length; k++) {
          newAttributesData.attributes.push({
            master_attribute_id: newAttributes[k].master_attribute_id,
            name: newAttributes[k].name,
            label: newAttributes[k].label,
            required: true,
            validation_required: true,
            is_multiple_value_required: false,
            type: newAttributes[k].type
          })
        }
        trueFormData.push(newAttributesData)
      }
      newPayload.forms_data = trueFormData
      setPayload(newPayload)
    }
  }, [selected])

  useEffect(() => {
    if (payload?.forms_data?.length > 0) {
      const data = payload?.forms_data
      const newDataSource = []
      for (let i = 0; i < data?.length; i++) {
        if (data[i].is_active) {
          newDataSource.push({
            no: i + 1,
            title: data[i]?.title,
            action: (
              <div className='questionnaire__action-wrapper'>
                <span
                  style={{ background: '#FADCDC' }}
                  onClick={() => {
                    handleRemoveForm(i)
                  }}
                >
                  <img src={DeleteIcon} height='16px' width='16px' />
                </span>
                <span
                  style={{ background: '#D2E6FA' }}
                  onClick={() => {
                    handleEditForm(i)
                  }}
                >
                  <img src={EditIcon} height='16px' width='16px' />
                </span>
              </div>
            )
          })
        }
      }
      setDataSource(newDataSource)
    } else setDataSource([])
  }, [payload])

  useEffect(() => {
    if (whichForm === 'add_quest') {
      setPayload({
        display_text: '',
        is_active: true,
        remark: 'text',
        forms_data: []
      })
    }
  }, [])

  const handleInputChange = (e) => {
    const newPayload = { ...payload }
    newPayload.display_text = e.target.value
    setPayload(newPayload)
  }

  const handleRemoveForm = (index) => {
    if (selected?.id) {
      const newPayload = { ...payload }
      newPayload.forms_data[index].is_active = false
      setPayload(newPayload)
    } else {
      const newPayload = { ...payload }
      newPayload.forms_data.splice(index, 1)
      setPayload(newPayload)
    }
  }
  const handleEditForm = (index) => {
    setFormId(index)
  }

  return (
    <ListformWrapper>
      <Form className='questionnaire__form-wrapper'>
        <FormItem label='Question Name'>
          {!firstTime && displayText
            ? (
              <div style={{ marginLeft: '10px' }}><Text strong>{displayText}</Text></div>
              )
            : (
              <Input
                onChange={handleInputChange}
                placeholder='Add Question Name'
                value={payload?.display_text}
              />
              )}
        </FormItem>
        <div className='questionnaire__table-wrapper'>
          <label>Form List</label>
          <Table
            style={{ overflow: 'auto' }}
            dataSource={dataSource}
            columns={columns}
          />
        </div>
        <div className='questionnaire__add-new-form'>
          <Button
            onClick={() => {
              setWhichForm('add')
            }}
          >
            ADD NEW FORM
          </Button>
        </div>
      </Form>
    </ListformWrapper>
  )
}

const CommonForm = Form.create()(ListForm)
const mapSateToProps = (state) => ({})

export default connect(mapSateToProps, {})(CommonForm)
