import { connect } from 'react-redux'
import { DeleteformWrapper } from './index.style'

function DeleteForm (props) {
  const { selected } = props
  const formsData = selected?.forms_data
  return (
    <DeleteformWrapper>
      <div className='questionnaire__delete-wrapper'>
        <p className='questionnaire__delete-ask'>
          Are you sure want to delete this question?
        </p>
        <div className='questionnaire__delete-card'>
          <div className='questionnaire__delete-card__up'>
            <div className='questionnaire__delete-card__item'>
              <label>Question</label>
              <p>{selected.display_text}</p>
            </div>
          </div>
          <div className='questionnaire__delete-card__down'>
            {formsData &&
              formsData?.length > 0 &&
              formsData.map((item, index) => {
                return (
                  <div className='questionnaire__delete-card__item' key={index}>
                    <label>Document {index + 1}</label>
                    <p>{item.title}</p>
                  </div>
                )
              })}
          </div>
        </div>
      </div>
    </DeleteformWrapper>
  )
}

const mapSateToProps = (state) => ({})

export default connect(mapSateToProps, {})(DeleteForm)
